            ['question' => 'How early should I arrive for my appointment?', 'answer' => 'Please arrive at least 15 minutes early unless staff gave you a different instruction. This gives time for check-in and preparation.', 'keywords' => 'arrive early, how early appointment, when should i arrive, check in time dialysis'],
            ['question' => 'Can I change my dialysis time slot?', 'answer' => 'Please contact {{clinic_contact_number}} to ask about changing your time slot. Availability depends on the clinic schedule and your treatment needs.', 'keywords' => 'change time slot, different dialysis time, move appointment time, change session time'],

            // ===== D. Symptoms, complications, and patient safety =====
            ['question' => 'What might I feel after dialysis?', 'answer' => 'Some tiredness after a session is common and usually passes within a few hours. Tell your care team if fatigue is severe or doesn\'t improve.', 'keywords' => 'feel after dialysis, tired after treatment, fatigue after dialysis'],
            ['question' => 'Is it normal to have muscle cramps or dizziness during dialysis?', 'answer' => 'Cramps and light dizziness can happen during a session. Tell staff immediately if this happens so they can help you — don\'t wait until after your session.', 'keywords' => 'muscle cramps, cramping during dialysis, dizziness during dialysis, feeling dizzy dialysis'],
            ['question' => 'What symptoms need urgent medical attention?', 'answer' => 'Severe chest pain, trouble breathing, fainting, or very heavy bleeding are emergencies — call emergency services or go to the nearest emergency room immediately. Do not wait for your next appointment.', 'keywords' => 'urgent symptoms, emergency symptoms, when to seek help, serious symptoms, chest pain dialysis'],
            ['question' => 'What should I do if my dialysis access is bleeding?', 'answer' => 'Apply firm, steady pressure to the site and contact the clinic or emergency services right away. Do not wait to see if it stops on its own.', 'keywords' => 'access bleeding, fistula bleeding, graft bleeding, bleeding access site'],
            ['question' => 'What should I do if I have a fever or signs of infection at my access site?', 'answer' => 'Contact our clinic staff or your doctor promptly — redness, swelling, warmth, or fever near your access site should not wait until your next scheduled visit.', 'keywords' => 'fever, infection, access site infection, signs of infection, red swollen access'],
            ['question' => 'I am worried about my treatment, who should I talk to?', 'answer' => 'Please talk to our dialysis staff or your doctor — they are there to answer your questions and address any concerns about your treatment.', 'keywords' => 'worried about treatment, concerned about dialysis, talk to someone, anxious about treatment'],

            ['question' => 'What should I do if I feel faint or have low blood pressure during dialysis?', 'answer' => 'Tell the dialysis staff immediately. Feeling faint, weak, sweaty, or light-headed during treatment needs prompt attention from the care team.', 'keywords' => 'faint during dialysis, low blood pressure dialysis, weak during session, sweaty dialysis, hypotension dialysis'],
            ['question' => 'What should I do if I feel nauseous or vomit during dialysis?', 'answer' => 'Tell the dialysis staff immediately so they can assess you and help. If this happens before your appointment, contact the center or your doctor for guidance.', 'keywords' => 'nausea during dialysis, vomiting dialysis, feel sick during session, throw up dialysis'],
            ['question' => 'What should I do if my access site is painful or swollen?', 'answer' => 'Contact the dialysis center or your doctor promptly. New pain, swelling, redness, warmth, or drainage near an access site should be assessed without waiting for a routine visit.', 'keywords' => 'painful fistula, swollen fistula, access site pain, access site swelling, painful catheter'],
            ['question' => 'What should I do if I have trouble breathing or chest pain?', 'answer' => 'Call emergency services or go to the nearest emergency room immediately. Do not wait for a chatbot reply, your next dialysis session, or a routine clinic call.', 'keywords' => 'trouble breathing, chest pain, shortness of breath, cannot breathe, breathing emergency'],
            ['question' => 'What should I do if I gain weight quickly between treatments?', 'answer' => 'Contact your dialysis team for advice, especially if you also have swelling or shortness of breath. Rapid weight changes can be important for patients on dialysis.', 'keywords' => 'weight gain between dialysis, rapid weight gain, swelling between sessions, fluid weight gain'],
            ['question' => 'Can I get medical advice from Diabot?', 'answer' => 'Diabot can provide general information, but it cannot diagnose symptoms, prescribe treatment, or replace advice from your doctor or dialysis care team.', 'keywords' => 'medical advice, diagnose me, diagnosis, prescribe medicine, chatbot doctor'],

            // ===== E. Billing and administrative questions =====
            ['question' => 'How much does dialysis treatment cost?', 'answer' => 'Costs can vary, and Diabot isn\'t able to quote fees. Please contact our billing staff at {{clinic_contact_number}} for accurate pricing information.', 'keywords' => 'cost of dialysis, price, how much is dialysis, treatment fees, dialysis cost'],
            ['question' => 'What payment methods do you accept?', 'answer' => 'Please ask our billing staff directly about accepted payment methods — this isn\'t something Diabot can confirm.', 'keywords' => 'payment methods, how to pay, accepted payments, ways to pay'],
