            ['question' => 'Does the clinic provide emergency care?', 'answer' => 'For a medical emergency, call emergency services or go to the nearest emergency room. Contact the center for questions about scheduled dialysis care.', 'keywords' => 'emergency care, emergency dialysis, emergency room, emergency treatment clinic'],
            ['question' => 'What should I do if I need directions to the clinic?', 'answer' => 'The center is located at {{clinic_address}}. You can use that address in your preferred map application or contact {{clinic_contact_number}} for help before you travel.', 'keywords' => 'directions to clinic, how to get there, map location, navigate to center, clinic directions'],
